<?php declare(strict_types=1); namespace Annam; $return_url=$return_url??'/manage/'.$key.'/'; $title=($id?'Edit ':'Add ').strtolower($spec['title']); ?>
<?php if($key==='dishes'&&$id):?><p><a class="o-btn" href="<?= e('/manage/dishes/'.$id.'/quantity/?'.http_build_query(['return_url'=>$return_url]+array_intersect_key($_GET,array_flip(['date','slot_id'])))) ?>">Manage quantity tracking</a></p><?php endif;?>
<a class="o-crumb" href="<?= e($return_url) ?>">← <?= e($spec['title']) ?></a><form method="post" enctype="multipart/form-data" class="o-form o-card"><?= csrf() ?><?php if(!empty($form_error)): ?><div class="o-flash o-flash-error" role="alert"><?= e($form_error) ?></div><?php endif; ?><input type="hidden" name="return_url" value="<?= e($return_url) ?>"><?php if(!empty($_GET['date'])&&$_GET['date']!=='all'&&!empty($_GET['slot_id'])): ?><input type="hidden" name="menu_date" value="<?= e($_GET['date']) ?>"><input type="hidden" name="menu_slot_id" value="<?= e($_GET['slot_id']) ?>"><input type="hidden" name="day_revision" value="<?= e($store->menuRevision($_GET['date'],(int)$_GET['slot_id'])) ?>"><label class="o-check"><?php $dateAvailable=true;if($id){$dateAvailable=false;foreach($store->menu($_GET['date'],(int)$_GET['slot_id'],true) as $entry)if((int)$entry['id']===$id)$dateAvailable=(bool)$entry['available'];} ?><input type="checkbox" name="day_available" value="1" <?= $dateAvailable?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span>Available on this date</span></label><?php endif; ?><section><div class="o-grid-form">
<?php if($key==='categories'):?><p class="o-field-wide">A dish photo is used automatically. No category photo upload is needed.</p><?php endif;?>
<?php foreach ($spec['fields'] as $field=>$definition): if($key==='dishes'&&(in_array($field,['weight','admin_notes'],true)||($field==='category_id'&&isset($fixed_category_id)&&isset(Catalog::DEFAULTS[(new Resources($store))->get('categories',(int)$fixed_category_id)['slug']]))))continue; [$label,$type]=explode('|',$definition);if($key==='dishes'&&$field==='category_id')$label='Extra category (optional)'; $value=$record[$field]??''; ?>
<?php if ($type==='bool'): ?><label class="o-check"><input type="hidden" name="<?= e($field) ?>" value="0"><input type="checkbox" name="<?= e($field) ?>" value="1" <?= $value?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span class="o-toggle-copy"><b><?= e($label) ?></b></span></label>
<?php elseif ($type==='slots'): $values=is_array($value)?$value:(is_string($value)?json_decode($value,true):[]); ?><fieldset class="php-fieldset"><legend><?= e($label) ?></legend><?php foreach (['breakfast','lunch','dinner','snacks'] as $meal): ?><label class="o-check"><input type="checkbox" name="slot_keys[]" value="<?= e($meal) ?>" <?= in_array($meal,$values?:[],true)?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span><?= e(ucfirst($meal)) ?></span></label><?php endforeach; ?><small>Select each meal this area serves.</small></fieldset>
<?php else: ?><label class="o-field"><span><?= e($label) ?></span>
<?php if ($type==='textarea'): ?><textarea name="<?= e($field) ?>" rows="5"><?= e($value) ?></textarea>
<?php elseif ($type==='fulfilment'): ?><select name="<?= e($field) ?>"><option value="scheduled" <?= $value==='scheduled'?'selected':'' ?>>Meals</option><option value="courier" <?= $value==='courier'?'selected':'' ?>>Shop products</option></select>
<?php elseif ($type==='category'): ?><select name="category_id" <?= isset($fixed_category_id)?'disabled':'' ?>><option value="">Use default category</option><?php foreach ($store->categories() as $cat): if($key==='dishes'&&isset(Catalog::DEFAULTS[$cat['slug']]))continue; ?><option value="<?= e($cat['id']) ?>" <?= (string)$value===(string)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select>
<?php else: ?><input name="<?= e($field) ?>" value="<?= e($value) ?>" type="<?= in_array($type,['time','optional_time'],true)?'time':(in_array($type,['price','int'],true)?'number':'text') ?>" <?= $type==='price'?'min="0" step="0.01"':($type==='int'?'min="0" step="1"':'') ?> <?= in_array($type,['text','price','time','slug','pincode'],true)?'required':'' ?>><?php endif; ?></label><?php endif; ?>
<?php if($field==='fulfilment'):?><?php if($key==='dishes'): $selectedMeals=$_POST['meals']??($id?(new Catalog($store))->meals($record):[]);if(!$id&&!$_POST){$contextMeal=isset($_GET['slot_id'])?$store->slot((int)$_GET['slot_id'])['key']:'';if(!$contextMeal&&isset($record['category_id']))$contextMeal=(new Resources($store))->get('categories',(int)$record['category_id'])['slug'];$selectedMeals=[isset(Catalog::MEALS[$contextMeal])?$contextMeal:'breakfast'];} ?><fieldset class="php-fieldset o-field-wide" data-meal-assignment <?= ($record['fulfilment']??'scheduled')==='courier'?'hidden':'' ?>><legend>Use this dish for</legend><input type="hidden" name="meals_present" value="1"><p class="o-catalog-hint">Create the dish once. Select every meal it belongs to, then choose its dates in Dishes &amp; products.</p><div class="o-btn-row"><?php foreach(Catalog::MEALS as $mealKey=>$mealName):?><label class="o-check"><input type="checkbox" name="meals[]" value="<?= e($mealKey) ?>" <?= in_array($mealKey,is_array($selectedMeals)?$selectedMeals:[],true)?'checked':'' ?>><span class="o-switch-ui"><i></i></span><b><?= e($mealName) ?></b></label><?php endforeach;?></div></fieldset><?php endif;?>
<?php endif;?>
<?php endforeach; ?>
<?php if($key==='dishes'): ?><label class="o-check"><input role="switch" type="checkbox" name="featured" value="1" <?= in_array('featured',json_decode($record['tags']??'[]',true),true)?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span class="o-toggle-copy"><b>Feature in popular products</b></span></label><?php endif; ?>
<?php if ($key!=='categories' && array_key_exists('image',$spec['defaults'])): ?><div class="o-field o-field-wide"><span>Photo</span><label class="o-drop" data-drop><img class="o-drop-preview" data-preview alt="" <?php if(!empty($record['image'])):?>src="<?= e(image_url($record['image'])) ?>"<?php else:?>hidden<?php endif;?>><span class="o-drop-hint"><svg class="o-ic"><use href="#o-upload"/></svg><b>Drop a photo here</b> or click to choose<small>JPG, PNG or WebP, up to 5 MB. Leave blank to keep the current photo.</small></span><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label></div><?php endif; ?></div></section><div class="o-form-bar"><a class="o-btn" href="<?= e($return_url) ?>">Cancel</a><button class="o-btn o-btn-primary" type="submit">Save changes →</button></div></form>
